namespace scratchbird::engine::internal_api { namespace { std::mutex m; using D=scratchbird::engine::sblr::SblrSecDropRoleDescriptorV1; std::map<std::string,D> live,used; std::string key(const D&v){return std::string(reinterpret_cast<const char*>(v.descriptor_evidence.data()),v.descriptor_evidence.size());} EngineApiDiagnostic d(std::string c,std::string k){return MakeEngineApiDiagnostic(std::move(c),std::move(k),{});} bool tag(const EngineRequestContext&c,const char*t){return c.security_context_present&&std::find(c.trace_tags.begin(),c.trace_tags.end(),t)!=c.trace_tags.end();} }
SblrSecDropRoleCoordinationResult CompileSblrSecDropRoleDescriptor(const EngineRequestContext&c,const std::string&r,std::uint64_t occurrence,std::uint64_t availability){std::lock_guard l(m);SblrSecDropRoleCoordinationResult o;if(!tag(c,"private_sec_drop_role_binder")||r!=c.statement_uuid.canonical||!occurrence||!availability){o.diagnostic=d("SBLR.OPERAND_INVALID","sblr.sec_drop_role.coordination_invalid");return o;}o.descriptor.availability=availability;o.descriptor.expected_generation=occurrence;auto b=scratchbird::engine::sblr::EncodeSblrSecDropRoleDescriptorV1(o.descriptor,false);if(!scratchbird::engine::sblr::DecodeSblrSecDropRoleDescriptorV1(b.data(),b.size(),&o.descriptor,nullptr,false)){o.diagnostic=d("SBLR.OPERAND_INVALID","sblr.sec_drop_role.descriptor_invalid");return o;}live[key(o.descriptor)]=o.descriptor;o.ok=true;o.diagnostic=d("OK","ok");return o;}
SblrSecDropRoleCoordinationResult ConsumeSblrSecDropRoleDescriptor(const EngineRequestContext&c,const D&v){std::lock_guard l(m);SblrSecDropRoleCoordinationResult o;auto k=key(v);if(!tag(c,"private_sec_drop_role")){o.diagnostic=d("SECURITY.ACCESS_DENIED","sblr.sec_drop_role.hidden");return o;}if(live.find(k)==live.end()){o.diagnostic=used.count(k)?d("MGA.TRANSACTION.STALE","sblr.sec_drop_role.stale"):d("SECURITY.ACCESS_DENIED","sblr.sec_drop_role.hidden");return o;}if(c.query_cancellation_requested&&c.query_cancellation_requested()){o.diagnostic=d("PROCESS.CANCELLED","sblr.sec_drop_role.cancelled");return o;}used[k]=v;live.erase(k);o.ok=true;o.descriptor=v;o.diagnostic=d("OK","ok");return o;}}
